def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    op = [h[1] for h in history]

    # Counts
    opp_c = 0
    opp_d = 0
    my_c = 0
    my_d = 0
    cc = cd = dc = dd = 0
    for a, b in history:
        if b == 'C':
            opp_c += 1
        else:
            opp_d += 1
        if a == 'C':
            my_c += 1
        else:
            my_d += 1
        if a == 'C' and b == 'C':
            cc += 1
        elif a == 'C' and b == 'D':
            cd += 1
        elif a == 'D' and b == 'C':
            dc += 1
        else:
            dd += 1

    # If opponent has never defected, cooperate (never spoil working relationship)
    if opp_d == 0:
        return 'C'

    # If opponent has always defected, defect
    if opp_c == 0:
        return 'D'

    last_me, last_op = history[-1]

    # Check recent window for assessing opponent
    w = 10 if n >= 10 else n
    rec_op_c = 0
    rec_op_d = 0
    rec_me_d = 0
    for i in range(n - w, n):
        a, b = history[i]
        if b == 'C':
            rec_op_c += 1
        else:
            rec_op_d += 1
        if a == 'D':
            rec_me_d += 1

    # Strong retaliation: if opponent has defected 3+ of last 10, defect
    if w >= 6 and rec_op_d >= 3:
        return 'D'

    # If opponent just defected, retaliate (with limited forgiveness for isolated D)
    if last_op == 'D':
        # Isolated defection after long cooperation: forgive once
        if opp_d == 1 and n >= 5:
            return 'C'
        # If we've already defected a lot recently, try to break DD lock
        if rec_me_d >= 4 and rec_op_c >= 3:
            return 'C'
        return 'D'

    # Opponent cooperated last round.
    # If we defected last round and they still cooperated, they're very forgiving:
    # reward them by cooperating to preserve the relationship.
    if last_me == 'D':
        return 'C'

    # Opponent is being nice consistently: cooperate
    if rec_op_c == w:
        return 'C'

    # If we've been too aggressive and opponent is mostly cooperative, repair
    if my_d > opp_d + 3 and opp_d <= 2:
        return 'C'

    return 'C'
